using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9: discriminator property renamed from "Discriminator" to "$type".
            // Existing 500K documents use "Discriminator" — keep the old name so reads
            // still work and direct SQL queries (c.Discriminator) remain valid.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9: id values no longer include the discriminator prefix.
            // Existing documents have ids like "Product|123" — keep the old format
            // so FindAsync and point-reads still resolve existing documents.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // EF Core 9: HasIndex on Cosmos entities now throws at startup.
        // Cosmos DB indexing is managed via the container's indexing policy
        // (Azure Portal / Bicep / Terraform), not through EF Core.
        // REMOVED: modelBuilder.Entity<Product>().HasIndex(p => p.Sku);
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

